head.b:template-skin:
/* TemaBlogger License Key: native Layout controls remain editable. */
body#layout .tb-license-settings{display:block!important;width:auto!important;clear:both!important;margin:0 0 16px!important;padding:12px!important;border:1px solid #d8e3f5!important;border-radius:12px!important;background:#f0f5ff!important}
body#layout .tb-license-settings .add_widget{display:none!important}
/* Dashboard only. Simple selectors and percentage columns survive Blogger's renderer. */
body#layout{margin:0;padding:18px;background:#f4f7f6;color:#263e34;font-family:Arial,Helvetica,sans-serif}
body#layout .wrap{width:auto;max-width:100%;padding:0;margin:0}
body#layout .site-header{position:relative;top:auto;right:auto;bottom:auto;left:auto;z-index:auto;height:auto;overflow:visible;background:transparent;color:#263e34;transform:none}
body#layout .header-top{display:block;position:relative;height:auto;overflow:visible;padding:0;background:transparent;visibility:visible}
body#layout .desktop-nav{display:block;height:auto;padding:0;overflow:visible}
body#layout .search-area{display:block;width:auto;max-width:none;height:auto;padding:0;margin:0}
body#layout .desktop-nav>.section{display:block}
body#layout .site-grid{display:block;width:auto;margin:14px 0;padding:14px;border:1px solid #cfded5;background:#fff;border-radius:7px}
body#layout .site-grid:before{display:block;content:'Konten Utama dan Sidebar';padding:0 0 13px;font-size:15px;font-weight:bold;color:#224f3d}
body#layout .site-grid:after{content:'';display:block;clear:both}
body#layout .main-column{display:inline-block;float:none;vertical-align:top;width:65%;min-width:280px;max-width:100%;margin:0 2% 0 0;padding:0}
body#layout .side-column{display:inline-block;float:none;vertical-align:top;width:32%;min-width:230px;max-width:100%;margin:0;padding:0}
body#layout .tbly-config,body#layout .tbly-header,body#layout .tbly-menu,body#layout .tbly-ads,body#layout .tbly-footer,body#layout .tbly-legacy{display:block;position:relative;top:auto;right:auto;bottom:auto;left:auto;width:auto;height:auto;max-height:none;margin:14px 0;padding:14px;border:1px solid #cfded5;border-radius:7px;background:#fff;overflow:visible;transform:none;clip-path:none}
body#layout .tbly-config{background:#eaf5ee;border-color:#b9d6c6}
body#layout .tbly-ads{background:#eff6fb;border-color:#c5dceb}
body#layout .tbly-config:before,body#layout .tbly-header:before,body#layout .tbly-menu:before,body#layout .tbly-ads:before,body#layout .tbly-footer:before,body#layout .tbly-legacy:before{display:block;margin:0 0 12px;color:#224f3d;font-size:15px;font-weight:bold;line-height:20px}
body#layout .tbly-config:before{content:'Konfigurasi'}
body#layout .tbly-header:before{content:'Header dan Logo'}
body#layout .tbly-menu:before{content:'Menu Navigasi'}
body#layout .tbly-ads:before{content:'Iklan Atas dan Melayang';color:#315c7b}
body#layout .tbly-footer:before{content:'Footer'}
body#layout .tbly-legacy:before{content:'Gadget Bawaan'}
body#layout .tbly-main,body#layout .tbly-side{display:block;width:auto;height:auto;margin:0;padding:0;background:transparent;border:0;border-radius:0;overflow:visible}
body#layout .tbly-main:before,body#layout .tbly-side:before{display:block;padding:0 0 10px;margin:0;color:#476253;font-size:13px;font-weight:bold}
body#layout .tbly-main:before{content:'Konten Utama'}
body#layout .tbly-side:before{content:'Sidebar'}
body#layout .tbly-main .tbly-ads,body#layout .tbly-side .tbly-ads{border:0;padding:0;margin:14px 0;background:transparent;border-radius:0}
body#layout .tbly-main .tbly-ads:before,body#layout .tbly-side .tbly-ads:before{font-size:12px;margin-bottom:8px}
body#layout .tbly-main .tbly-ads:before{content:'Postingan Blog dan Iklan Artikel'}
body#layout .tbly-side .tbly-ads:before{content:'Iklan Sidebar'}
body#layout .section{display:block;position:relative;top:auto;right:auto;bottom:auto;left:auto;width:auto;height:auto;min-height:0;max-height:none;margin:0 0 12px;padding:0;border:0;background:transparent;overflow:visible;transform:none;clip-path:none;visibility:visible}
body#layout .section h4{font-size:12px;margin:11px 0 7px;color:#52695d;line-height:18px}
body#layout .section .widget{display:block;float:none;position:relative;width:auto;max-width:none;min-width:0;height:auto;min-height:55px;margin:0 0 8px;background:#fff;border:1px solid #d4dfd8;border-radius:4px;overflow:visible;visibility:visible}
body#layout .section .widget .widget-content{display:block;position:relative;height:auto;max-height:none;min-height:0;overflow:visible;white-space:normal;line-height:1.45}
body#layout .section .add_widget{display:none!important}
body#layout .ad-section .widget,body#layout .tb-ad-section .widget{background:#edf6fc;border-color:#c6ddea}
body#layout .ad-slot,body#layout .ad-window,body#layout .ad-creative,body#layout .ad-parallax,body#layout .ad-top,body#layout .ad-rail,body#layout .ad-bottom,body#layout .ad-holder{display:block;position:relative;top:auto;right:auto;bottom:auto;left:auto;width:auto;height:auto;min-height:0;max-height:none;margin:0;padding:0;overflow:visible;transform:none;clip-path:none}
body#layout .site-footer{display:block;position:relative;margin:0;background:transparent;font-family:Arial,Helvetica,sans-serif}
body#layout .footer-inner{display:block;padding:0;margin:0;width:auto}
body#layout .footer-copy{padding:0;border:0;background:transparent;text-align:left}
body#layout .config-data,body#layout .config-source,body#layout .module-config,body#layout .legacy-public-hidden,body#layout .legacy-widgets,body#layout .home-only,body#layout .article-only,body#layout .extra-home-blocks,body#layout .after-headline-ad{display:block;position:relative;width:auto;height:auto;min-height:0;max-height:none;top:auto;right:auto;bottom:auto;left:auto;overflow:visible;visibility:visible;transform:none;clip-path:none}
body#layout .menu-panel,body#layout .search-panel,body#layout .search-overlay,body#layout .skip-link,body#layout .mobile-tabs,body#layout .topic-bar,body#layout .back-top{display:none}

body#layout .site-grid .main-column{display:inline-block;width:65%;min-width:280px;max-width:100%;vertical-align:top;margin:0 2% 0 0;padding:0}
body#layout .site-grid .side-column{display:inline-block;width:32%;min-width:230px;max-width:100%;vertical-align:top;margin:0;padding:0}
body#layout .sidebar-end{display:block}
body#layout .topic-bar{display:block;position:relative;height:auto;padding:14px;margin:14px 0;border:1px solid #cfded5;background:white;overflow:visible}
body#layout .topic-bar:before{content:"Topik Pilihan";display:block;font-weight:bold;margin-bottom:12px}
body#layout .topic-track,body#layout .topic-prev,body#layout .topic-next{display:none}
body#layout .ad-section-sticky{position:relative;top:auto;right:auto;bottom:auto;left:auto}
body#layout div.section{border:0!important;background:transparent!important;padding:0!important}

body#layout .header-slot{display:block;position:relative;top:auto;height:auto;z-index:auto}

b:if.script:
//
/* tb-identity-presentation-b-20261107: native logo and exact stock credit presentation only. */
(function(){
 'use strict';
 var cfg={"slug":"tbsport","kind":"customer","source":"#Header1 .brand","native":true,"mirror":"[data-tb-logo-mirror=\"tbsport\"]","creditTargets":""};
 var queued=false;
 function tidy(s){return String(s||'').replace(/\s+/g,' ').trim();}
 function stockCredit(el){
  var text=tidy(el.textContent),links=el.querySelectorAll('a');
  var linked=/^Copyright © (\d{4})(?:\.)? Tema Blogger(?: \.)?\.?(?: )All rights reserved\.$/.exec(text);
  var year=linked&&linked[1];
  if(linked){
   if(links.length!==1||tidy(links[0].textContent)!=='Tema Blogger'||links[0].getAttribute('href')!=="https://www.temablogger.com/")return;
  }else{
   var legacy=cfg.slug==='saetimes'&&cfg.kind==='demo'&&/^© (\d{4}) SAETIMES\. All Right Reserved\.$/.exec(text);
   if(!legacy||links.length!==0)return;year=legacy[1];
  }
  var a=document.createElement('a');a.href="https://www.temablogger.com/";a.textContent='Tema Blogger';
  var y=el.querySelector('#year');if(y)y.textContent=year;
  el.replaceChildren(document.createTextNode('© '),y||document.createTextNode(year),document.createTextNode(' '),a,document.createTextNode('. All rights reserved.'));
 }
 function mirror(){
  if(!cfg.source)return;
  var src=document.querySelector(cfg.source);if(!src)return;
  var img=src.querySelector('img'),title=document.getElementById('tb-identity-blog-title');
  var name=cfg.native?tidy(title&&title.textContent):tidy(src.textContent);
  if(img)name=img.getAttribute('alt')||tidy(title&&title.textContent);
  if(!name)name=tidy(title&&title.textContent);
  document.querySelectorAll(cfg.mirror).forEach(function(target){
   if(target===src||src.contains(target))return;
   if(img&&img.getAttribute('src')){
    var old=target.querySelector('img');if(old&&old.getAttribute('src')===img.getAttribute('src'))return;
    var copy=img.cloneNode(true);copy.removeAttribute('id');copy.removeAttribute('width');copy.removeAttribute('height');
    target.replaceChildren(copy);
   }else if(name&&tidy(target.textContent)!==name)target.textContent=name;
  });
 }
 function apply(){queued=false;if(!document.body||document.body.id==='layout')return;
  if(cfg.creditTargets)document.querySelectorAll(cfg.creditTargets).forEach(stockCredit);
  mirror();
 }
 function schedule(){if(queued)return;queued=true;(window.requestAnimationFrame||function(f){setTimeout(f,0);})(apply);}
 function start(){apply();if(window.MutationObserver&&document.body)new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true});}
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();
//
